export default async function next({ event, acknowledge, resolution, confirmedId }, ctx) {
  const email = event?.payload?.email;
  const id = event?.payload?.uri;
  if (typeof id !== "string" || !id || typeof email !== "string" || !email)
    throw Error("Expected Calendly invitee URI and email");
  const key = "calendly-enrich:" + id;
  let state = await ctx.state.get(key);
  if (!state) {
    const personal = [
      "@gmail.com",
      "@yahoo.com",
      "@outlook.com",
      "@hotmail.com",
      "@icloud.com",
      "@mail.com",
      "@aol.com",
      "@zoho.com",
      "@gmx",
    ].some((x) => email.includes(x));
    state = { phase: personal ? "done" : "person", email, pending: null };
    await ctx.state.set(key, state);
  }
  if (state.pending) {
    if (acknowledge !== state.pending || !["confirmed", "absent"].includes(resolution))
      throw Error("Inspect pending write: " + state.pending);
    if (resolution === "confirmed") {
      if (state.phase === "create-company") {
        if (!confirmedId) throw Error("Enter the confirmed company ID");
        state.companyId = confirmedId;
        state.phase = "contact";
      } else if (state.phase === "contact" && state.companyId) {
        if (!confirmedId) throw Error("Enter the confirmed contact ID");
        state.contactId = confirmedId;
        state.phase = "associate";
      } else state.phase = "done";
    }
    state.pending = null;
    await ctx.state.set(key, state);
  }
  const phase = state.phase;
  if (["create-company", "update-company", "contact", "associate"].includes(phase)) {
    state.pending = phase + ":" + id;
    await ctx.state.set(key, state);
  }
  const c = state.company || {},
    person = state.person || {};
  const properties = Object.fromEntries(
    Object.entries({
      name: c.name,
      domain: c.domain,
      description: c.description,
      founded_year: c.foundedYear,
      country: c.geo?.country,
      twitterbio: c.twitter?.bio,
      twitterhandle: c.twitter?.handle,
      twitterfollowers: c.twitter?.followers,
      total_money_raised: c.metrics?.raised,
      numberofemployees: c.metrics?.employees,
    }).filter(([, v]) => v != null && v !== ""),
  );
  if (phase === "update-company") {
    delete properties.name;
    delete properties.domain;
    delete properties.founded_year;
  }
  const contactProperties = state.companyId
    ? []
    : [
        { property: "firstname", value: person.name?.fullName || "" },
        { property: "lastname", value: person.name?.familyName || "" },
      ];
  if (
    phase === "associate" &&
    ![state.contactId, state.companyId].every(
      (x) => /^\d+$/.test(String(x)) && Number.isSafeInteger(Number(x)),
    )
  )
    throw Error("HubSpot association needs numeric contact and company IDs");
  return {
    properties,
    filters: [
      { filters: [{ propertyName: "domain", operator: "EQ", value: state.domain || "." }] },
    ],
    contactUrl:
      "https://api.hubapi.com/contacts/v1/contact/createOrUpdate/email/" +
      encodeURIComponent(state.email),
    contactBody: { properties: contactProperties },
    associationUrl: "https://api.hubapi.com/crm-associations/v1/associations/create-batch",
    associationBody: [
      {
        fromObjectId: Number(state.contactId || 0),
        toObjectId: Number(state.companyId || 0),
        category: "HUBSPOT_DEFINED",
        definitionId: 1,
      },
    ],
    phase,
    key,
    email: state.email,
    personUrl:
      "https://person.clearbit.com/v2/people/find?email=" + encodeURIComponent(state.email),
    companyUrl:
      "https://company.clearbit.com/v2/companies/find?domain=" +
      encodeURIComponent(state.domain || ""),
    companyId: state.companyId || ".",
    contactId: state.contactId || ".",
    company: state.company || {},
    person: state.person || {},
  };
}

