async function result({ key, phase, body, statusCode, records, record }, ctx) {
  const state = await ctx.state.get(key);
  if (!state || state.phase !== phase) throw Error("Unexpected reporting phase");
  if (phase === "person") {
    if (statusCode === 404) state.phase = "done";
    else {
      if (statusCode !== 200 || !body || typeof body.email !== "string")
        throw Error("Person enrichment did not return a completed record");
      state.person = body;
      state.domain = body.employment?.domain || "";
      state.phase = state.domain ? "company" : "contact";
    }
  } else if (phase === "company") {
    if (statusCode !== 200 || !body || typeof body.domain !== "string")
      throw Error("Company enrichment did not return a completed record");
    state.company = body;
    state.phase = "search-company";
  } else if (phase === "search-company") {
    if (!Array.isArray(records)) throw Error("Company search returned no result list");
    if (records.length) {
      if (!records[0]?.id) throw Error("Company search returned no ID");
      state.companyId = records[0].id;
      state.phase = "update-company";
    } else state.phase = "create-company";
  } else if (phase === "create-company") {
    if (!record?.id) throw Error("Company creation returned no ID");
    state.companyId = record.id;
    state.pending = null;
    state.phase = "contact";
  } else if (phase === "update-company") {
    if (!record?.id) throw Error("Company update returned no ID");
    state.pending = null;
    state.phase = "done";
  } else if (phase === "contact") {
    if (statusCode < 200 || statusCode >= 300 || !body?.vid)
      throw Error("Contact upsert was not confirmed");
    state.contactId = String(body.vid);
    state.pending = null;
    state.phase = state.companyId ? "associate" : "done";
  } else if (phase === "associate") {
    if (statusCode < 200 || statusCode >= 300) throw Error("Association was not confirmed");
    state.pending = null;
    state.phase = "done";
  } else throw Error("Unknown phase");
  await ctx.state.set(key, state);
  return { ok: true };
}

export default async function run(input, ctx) {
  return result({ ...input, phase: "person" }, ctx);
}

